"""
Build the Shopify INVENTORY CSV (stock by location) in Shopify's current
"inventory bin / on-hand" template format, matching the product CSV generated by
build_full_catalog.py (same SKU + URL handle, same qty-3 safety buffer).

Import AFTER the product CSV: it sets "On hand (new)" per variant by Handle/SKU.

Usage: python build_inventory_csv.py [xlsx] [out_file]
"""
import os
import re
import csv
import glob
import argparse
import warnings
from typing import Any, Dict, List

warnings.filterwarnings("ignore")

sys = __import__("sys")
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import build_full_catalog as core  # reuse money/num/slug + SAFETY_BUFFER

# exact header order from Shopify's inventory template
FIELDNAMES = [
    "Handle", "Title", "Option1 Name", "Option1 Value", "Option2 Name", "Option2 Value",
    "Option3 Name", "Option3 Value", "SKU", "HS Code", "COO", "Location", "Bin name",
    "Incoming (not editable)", "Unavailable (not editable)", "Committed (not editable)",
    "Available (not editable)", "On hand (current)", "On hand (new)",
    "Variant Packed Length", "Variant Packed Width", "Variant Packed Height",
    "Variant Packed Dimension Unit",
]

LOCATION = "Shop location"


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("xlsx", nargs="?", default=sorted(glob.glob(
        os.path.expanduser("~/Downloads/Aosom ESStore Products *.xlsx")))[-1])
    ap.add_argument("out", nargs="?", default=os.path.join(
        os.path.dirname(os.path.abspath(__file__)), "..", "shopify_import_full", "inventory_on_hand.csv"))
    args = ap.parse_args()

    rows: List[Dict[str, str]] = []
    seen = set()

    for row, idx in core.iter_catalog(args.xlsx):
        sku = str(row[idx["Seller SKU"]] or "").strip()
        name = str(row[idx.get("Product Name (Spanish)")] or row[idx["Product Name"]] or "").strip()
        if not sku or not name or sku in seen:
            continue
        seen.add(sku)
        qty = int(core.num(row[idx.get("Qty Available")]))
        avail = max(0, qty - core.SAFETY_BUFFER)
        sku_clean = re.sub(r"\s+", "-", sku).upper()
        handle = f"{core.slug(sku_clean)}-{core.slug(name)}"
        rows.append({
            "Handle": handle,
            "Title": name,
            "Option1 Name": "Title",
            "Option1 Value": "Default Title",
            "SKU": sku_clean,
            "Location": LOCATION,
            "On hand (new)": str(avail),
        })

    with open(args.out, "w", newline="", encoding="utf-8-sig") as fh:
        w = csv.DictWriter(fh, fieldnames=FIELDNAMES)
        w.writeheader()
        for r in rows:
            w.writerow({k: r.get(k, "") for k in FIELDNAMES})

    stocked = sum(1 for r in rows if int(r["On hand (new)"]) > 0)
    print(f"rows: {len(rows)}  with stock>0: {stocked}  -> {args.out}")


if __name__ == "__main__":
    main()
